CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, openid VARCHAR(128) NOT NULL UNIQUE, unionid VARCHAR(128), nickname VARCHAR(128), avatar_url VARCHAR(512), country VARCHAR(64), province VARCHAR(64), city VARCHAR(64), gender INTEGER NOT NULL DEFAULT 0, status INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS wechat_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, code VARCHAR(128) NOT NULL UNIQUE, openid VARCHAR(128) NOT NULL, session_key VARCHAR(256) NOT NULL, expires_at TIMESTAMP, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS daily_steps (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, step_date DATE NOT NULL, step_count INTEGER NOT NULL DEFAULT 0, raw_payload TEXT, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, UNIQUE(user_id, step_date));
CREATE TABLE IF NOT EXISTS step_exchanges (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, exchange_date DATE NOT NULL, step_count INTEGER NOT NULL DEFAULT 0, mileage INTEGER NOT NULL DEFAULT 0, step_unit INTEGER NOT NULL DEFAULT 100, mileage_unit INTEGER NOT NULL DEFAULT 20, status INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL, UNIQUE(user_id, exchange_date));
CREATE TABLE IF NOT EXISTS route_nodes (id INTEGER PRIMARY KEY AUTOINCREMENT, node_order INTEGER NOT NULL UNIQUE, local_id VARCHAR(64) NOT NULL, city_name VARCHAR(128) NOT NULL UNIQUE, longitude DECIMAL(10,6) NOT NULL, latitude DECIMAL(10,6) NOT NULL, required_mileage INTEGER NOT NULL, badge_code VARCHAR(64), city_image VARCHAR(512), city_detail TEXT, enabled INTEGER NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
CREATE TABLE IF NOT EXISTS system_configs (id INTEGER PRIMARY KEY AUTOINCREMENT, config_key VARCHAR(128) NOT NULL UNIQUE, config_value VARCHAR(256) NOT NULL, description VARCHAR(256), created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL);
